import{c as e,Q as o,j as i,m as t}from"./chunks/framework.BXc4yaFE.js";const b=JSON.parse('{"title":"Clarus: Coordinating Autonomous Research Agents toward Web-Scale Scientific Collaboration","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.30246","title":"Clarus: Coordinating Autonomous Research Agents toward Web-Scale Scientific Collaboration","archived_date":"2026-07-27T00:00:00.000Z","arxiv_id":2606.30246,"authors":["Zihan Guo","Zeyi Chen","Zhiyu Chen","Zicai Cui","Shuai Shao","Bo Huang","Zhi Han","Yuanyi Song","Yuan Yuan","Chenxi Zeng","Xiaohang Nie","Zhengxi Yu","Hanwen Zhu","Junwei Liao","Ming Zhou","Yang Li","Yuanjian Zhou","Weinan Zhang"],"domain":"hypothesis-generation-infrastructure","published_date":"2026-06-29T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-27-clarus-web-scale-scientific-collaboration-2606-30246.md","filePath":"research/papers/2026-07-27-clarus-web-scale-scientific-collaboration-2606-30246.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-07-27-clarus-web-scale-scientific-collaboration-2606-30246.md"};function n(s,a,c,l,u,h){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="clarus-coordinating-autonomous-research-agents-toward-web-scale-scientific-collaboration" tabindex="-1">Clarus: Coordinating Autonomous Research Agents toward Web-Scale Scientific Collaboration <a class="header-anchor" href="#clarus-coordinating-autonomous-research-agents-toward-web-scale-scientific-collaboration" aria-label="Permalink to &quot;Clarus: Coordinating Autonomous Research Agents toward Web-Scale Scientific Collaboration&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>主張現有自主研究工具多為孤立助手而非真正協作平台，提出 Clarus 作為跨參與者（含人類研究者、團隊、實驗室、組織，非僅 AI）協調科研的基礎設施。以四層架構（Research Application／Digital Collaboration／Physical Substrate／Physical World）組織科研工作，目標使研究「開放、可稽核、可歸因、資源感知」，並建立「可溯源、可審查、可歸因、可累積」的協作網路信任機制。透過協作論文生成的案例研究驗證，展示 Clarus 如何把研究目標組織成跨多階段、多參與者的協調工作流。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>「多參與者科研協作基礎設施」與 workspace 既有覆蓋（agent harness／單一委派拓撲）無語意重疊；核心關鍵詞 co-scientist（本文所涉概念族群）於既有覆蓋集合反向 grep 命中為 0。</p>',5)])])}const p=e(r,[["render",n]]);export{b as __pageData,p as default};
